// Redemption code (task 52; REQ-03-11; spec 3.7.4): six characters from A-Z and 2-9 without I and O, generated by a
// CSPRNG when the capture completes; uniqueness is the database's uq_purchases_redemption_code (retried on collision).
import { randomInt } from 'node:crypto';
import { REDEMPTION_CODE_ALPHABET, REDEMPTION_CODE_LENGTH } from '../../shared/types.js';

export function generateRedemptionCode(rand: (max: number) => number = randomInt): string {
  let code = '';
  for (let i = 0; i < REDEMPTION_CODE_LENGTH; i++) code += REDEMPTION_CODE_ALPHABET[rand(REDEMPTION_CODE_ALPHABET.length)];
  return code;
}
